<?php require __DIR__.'/bootstrap.php';require_login();require __DIR__.'/movidesk.php';require __DIR__.'/portal-data.php';$u=$_SESSION['user'];if($u['role']!=='client'||!$u['company_id']){http_response_code(403);exit('Acesso restrito.');}$ticketId=max(1,(int)($_GET['id']??0));$month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??'')?$_GET['month']:date('Y-m');$st=$pdo->prepare("SELECT ct.* FROM contracts ct JOIN companies c ON c.id=ct.company_id WHERE ct.company_id=? AND ct.status='active' AND c.status='active' ORDER BY ct.id DESC LIMIT 1");$st->execute([$u['company_id']]);$contract=$st->fetch();if(!$contract){http_response_code(404);exit('Contrato não encontrado.');}$allowed=false;try{$usage=portal_consumption($contract['name'],$month);foreach($usage['appointments'] as $entry)if((int)($entry['ticketNumber']??0)===$ticketId){$allowed=true;break;}}catch(Throwable $e){http_response_code(503);exit('Não foi possível validar este atendimento agora.');}if(!$allowed){http_response_code(403);exit('Este chamado não pertence aos atendimentos disponíveis para sua empresa nesta competência.');}$ticket=movidesk_ticket_cached($ticketId);if(isset($ticket[0])&&is_array($ticket[0]))$ticket=$ticket[0];$actions=array_values(array_filter($ticket['actions']??[],static fn($action)=>(int)($action['type']??0)===2));
function safe_client_action(string $html):string{if(trim($html)==='')return '<p>Sem descrição textual.</p>';if(!class_exists('DOMDocument'))return '<p>'.nl2br(e(strip_tags($html))).'</p>';$doc=new DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8"><div id="safe-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($old);$allowed=['div','span','p','br','strong','b','em','i','u','ul','ol','li','table','thead','tbody','tfoot','tr','th','td','a'];$nodes=[];foreach($doc->getElementsByTagName('*') as $n)$nodes[]=$n;for($i=count($nodes)-1;$i>=0;$i--){$n=$nodes[$i];$tag=strtolower($n->nodeName);if($n->getAttribute('id')==='safe-root')continue;if(!in_array($tag,$allowed,true)){if(in_array($tag,['script','style','iframe','object','embed','img','svg'],true))$n->parentNode?->removeChild($n);else{while($n->firstChild)$n->parentNode?->insertBefore($n->firstChild,$n);$n->parentNode?->removeChild($n);}continue;}$keep=[];if(in_array($tag,['td','th'],true))foreach(['colspan','rowspan'] as $a)if(ctype_digit($n->getAttribute($a)))$keep[$a]=$n->getAttribute($a);if($tag==='a'){$href=trim($n->getAttribute('href'));if(preg_match('#^(https?://|mailto:)#i',$href))$keep['href']=$href;}$remove=[];foreach($n->attributes??[] as $a)$remove[]=$a->name;foreach($remove as $a)$n->removeAttribute($a);foreach($keep as $a=>$v)$n->setAttribute($a,$v);if($tag==='a'&&isset($keep['href'])){$n->setAttribute('target','_blank');$n->setAttribute('rel','noopener noreferrer');}}$root=$doc->getElementById('safe-root');$out='';if($root)foreach($root->childNodes as $child)$out.=$doc->saveHTML($child);return trim($out)?:'<p>Sem descrição textual.</p>';}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Chamado #<?=$ticketId?> | Newsiga</title><link rel="stylesheet" href="assets/style.css"><style>.ticket-page{width:min(980px,calc(100% - 32px));margin:38px auto;background:#fff;padding:42px;border:1px solid #d9dfda;overflow:hidden}.ticket-page h1{font-size:clamp(32px,5vw,42px);margin-bottom:24px}.ticket-subject{font-size:20px;line-height:1.3;overflow-wrap:anywhere}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:24px 0 34px}.meta article{padding:18px;background:#f2f4ef;border:1px solid #d9dfda}.meta small{display:block;color:#64766f;font-weight:700;margin-bottom:9px}.action{padding:20px 0;border-top:1px solid #d9dfda}.action-head{display:flex;justify-content:space-between;color:#64766f;font-size:11px}.action h3{font-size:14px;margin:9px 0}.action-body{font-size:14px;line-height:1.55;overflow-wrap:anywhere;word-break:break-word}.action-body table{width:100%;margin:14px 0;border-collapse:collapse;table-layout:fixed}.action-body th,.action-body td{padding:9px;border:1px solid #d3dbd6;text-align:center}.action-body th{background:#f2f4ef}.back{display:inline-flex;margin-top:28px;padding:12px 17px;border:1px solid #cbd5d0;color:#0c2a23;font-size:12px;font-weight:700;text-decoration:none}@media(max-width:700px){.ticket-page{padding:25px}.meta{grid-template-columns:1fr}.action-body{overflow:auto}.action-body table{min-width:520px}}</style></head><body><header class="top"><a class="brand" href="<?=url('dashboard.php')?>">newsiga</a><nav><a href="<?=url('profile.php')?>">Minha conta</a><a href="<?=url('logout.php')?>">Sair</a></nav></header><main class="ticket-page"><p class="kicker" style="margin-top:0">DETALHES DO ATENDIMENTO</p><h1>Chamado #<?=$ticketId?></h1><h2 class="ticket-subject"><?=e((string)($ticket['subject']??'Sem assunto'))?></h2><section class="meta"><article><small>STATUS</small><strong><?=e((string)($ticket['status']??'—'))?></strong></article><article><small>URGÊNCIA</small><strong><?=e((string)($ticket['urgency']??'—'))?></strong></article><article><small>AÇÕES PÚBLICAS</small><strong><?=count($actions)?></strong></article></section><section><h2>Ações do ticket</h2><?php foreach($actions as $action):?><article class="action"><div class="action-head"><span>Ação #<?=e((string)($action['id']??'—'))?></span><span><?=e((string)($action['createdDate']??''))?></span></div><h3><?=e((string)($action['createdBy']['businessName']??'Autor não informado'))?></h3><div class="action-body"><?=safe_client_action((string)($action['htmlDescription']??$action['description']??''))?></div></article><?php endforeach;?></section><a class="back" href="<?=url('dashboard.php?month='.urlencode($month))?>">← Voltar aos chamados</a></main></body></html>
